--
-- Name: generate_license_key(character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_license_key(p_application character varying, p_tier character varying, p_tenant_id uuid) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tenant_hash VARCHAR;
    v_timestamp VARCHAR;
    v_random VARCHAR;
    v_checksum VARCHAR;
BEGIN
    -- Create tenant hash (first 8 chars of MD5)
    v_tenant_hash := UPPER(SUBSTRING(MD5(p_tenant_id::TEXT) FROM 1 FOR 8));
    
    -- Timestamp (YYYYMMDD)
    v_timestamp := TO_CHAR(NOW(), 'YYYYMMDD');
    
    -- Random component
    v_random := UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 6));
    
    -- Build key: QASSURE-{APP}-{TIER}-{HASH}-{TIMESTAMP}-{RANDOM}
    RETURN 'QASSURE-' || UPPER(p_application) || '-' || UPPER(SUBSTRING(p_tier FROM 1 FOR 3)) || '-' || 
           v_tenant_hash || '-' || v_timestamp || '-' || v_random;
END;
$$;


