--
-- Name: update_storage_usage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_storage_usage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE storage_quotas 
    SET used_storage_bytes = used_storage_bytes + NEW.file_size,
        file_count = file_count + 1,
        updated_at = NOW()
    WHERE tenant_id = NEW.tenant_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' AND OLD.deleted_at IS NULL THEN
    UPDATE storage_quotas 
    SET used_storage_bytes = used_storage_bytes - OLD.file_size,
        file_count = file_count - 1,
        updated_at = NOW()
    WHERE tenant_id = OLD.tenant_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


